# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HUTBE İLE VAAZ ARASINDAKİ TEMEL FARKLAR</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">HUTBE (Minber Hitabeti)</text>\n  <rect x="35" y="78" width="290" height="128" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10" fill="#334155">• Mekân ve Duruş: Minberde ve ayakta okunur.</text>\n  <text x="180" y="118" text-anchor="middle" font-size="10" fill="#334155">• Zaman: Cuma namazından önce, bayram namazından sonra.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="10" fill="#334155">• Hüküm: Cuma namazında farz, bayramda sünnettir.</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10" fill="#334155">• Şekil: İki bölümden oluşur, arada kısa oturulur.</text>\n  <text x="180" y="178" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">• Süre: Kısa, öz ve vecizdir (10-15 dakika).</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">VAAZ (Kürsü Hitabeti)</text>\n  <rect x="375" y="78" width="290" height="128" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.2"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" fill="#334155">• Mekân ve Duruş: Kürsüde ve oturarak yapılır.</text>\n  <text x="520" y="118" text-anchor="middle" font-size="10" fill="#334155">• Zaman: Cuma/vakit namazları öncesi, kandiller, her vakit.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="10" fill="#334155">• Hüküm: Namazın şartı değildir; genel irşat görevidir.</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10" fill="#334155">• Şekil: Tek bölümdür (Giriş - Gelişme - Sonuç/Dua).</text>\n  <text x="520" y="178" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">• Süre: Konuyu ayrıntılı işler (25-40 dakika).</text>\n</svg>', '<svg viewBox="0 0 700 220" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="220" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">VAAZ PLANININ AŞAMALARI VE BÖLÜMLERİ</text>\n  <rect x="20" y="50" width="210" height="148" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. GİRİŞ BÖLÜMÜ</text>\n  <text x="125" y="96" text-anchor="middle" font-size="10" fill="#334155">• Cemaati selamlama</text>\n  <text x="125" y="114" text-anchor="middle" font-size="10" fill="#334155">• Eûzü-Besmele, Hamdele, Salvele</text>\n  <text x="125" y="132" text-anchor="middle" font-size="10" fill="#334155">• Konuyla ilgili Aşr-ı Şerif</text>\n  <text x="125" y="150" text-anchor="middle" font-size="10" fill="#334155">• Konunun takdimi ve dikkat çekme</text>\n\n  <line x1="230" y1="124" x2="245" y2="124" stroke="#475569" stroke-width="2"/>\n  <polygon points="245,124 238,119 238,129" fill="#475569"/>\n\n  <rect x="245" y="50" width="210" height="148" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">2. GELİŞME BÖLÜMÜ</text>\n  <text x="350" y="96" text-anchor="middle" font-size="10" fill="#334155">• Ayet ve sahih hadislerle analiz</text>\n  <text x="350" y="114" text-anchor="middle" font-size="10" fill="#334155">• Asr-ı Saadet\'ten örnek tablolar</text>\n  <text x="350" y="132" text-anchor="middle" font-size="10" fill="#334155">• Güncel bireysel/toplumsal bağlam</text>\n  <text x="350" y="150" text-anchor="middle" font-size="10" fill="#334155">• Müjdeleyici (tebşir) üslup</text>\n\n  <line x1="455" y1="124" x2="470" y2="124" stroke="#475569" stroke-width="2"/>\n  <polygon points="470,124 463,119 463,129" fill="#475569"/>\n\n  <rect x="470" y="50" width="210" height="148" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">3. SONUÇ VE DUA</text>\n  <text x="575" y="96" text-anchor="middle" font-size="10" fill="#334155">• Ana mesajların veciz özeti</text>\n  <text x="575" y="114" text-anchor="middle" font-size="10" fill="#334155">• Ezan vaktiyle uyumlu bitiş</text>\n  <text x="575" y="132" text-anchor="middle" font-size="10" fill="#334155">• Konuyla bütünleşen Türkçe dua</text>\n  <text x="575" y="150" text-anchor="middle" font-size="10" fill="#334155">• Salavat ve Fâtiha ile kapanış</text>\n</svg>', '<svg viewBox="0 0 700 210" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="210" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ETKİLİ BİR VAİZDE BULUNMASI GEREKEN İLKELER</text>\n  <rect x="20" y="48" width="210" height="142" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">İLMÎ HAZIRLIK VE PLAN</text>\n  <text x="125" y="96" text-anchor="middle" font-size="10" fill="#334155">• Konu sınırlandırması ve plan</text>\n  <text x="125" y="114" text-anchor="middle" font-size="10" fill="#334155">• Sahih ayet ve hadis kullanımı</text>\n  <text x="125" y="132" text-anchor="middle" font-size="10" fill="#334155">• Hurafe ve mevzûdan kaçınma</text>\n  <text x="125" y="150" text-anchor="middle" font-size="10" fill="#334155">• Zaman yönetimi (ezan uyumu)</text>\n\n  <rect x="245" y="48" width="210" height="142" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">ÜSLUP VE İLETİŞİM</text>\n  <text x="350" y="96" text-anchor="middle" font-size="10" fill="#334155">• Tebşir (müjdeleyici) dil</text>\n  <text x="350" y="114" text-anchor="middle" font-size="10" fill="#334155">• Teysir (kolaylaştırıcı) yaklaşım</text>\n  <text x="350" y="132" text-anchor="middle" font-size="10" fill="#334155">• Kuşatıcı ve birleştirici hitap</text>\n  <text x="350" y="150" text-anchor="middle" font-size="10" fill="#334155">• Temsil (söz-davranış uyumu)</text>\n\n  <rect x="470" y="48" width="210" height="142" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">SUNUM VE BEDEN DİLİ</text>\n  <text x="575" y="96" text-anchor="middle" font-size="10" fill="#334155">• Temiz ve vakur dış görünüş</text>\n  <text x="575" y="114" text-anchor="middle" font-size="10" fill="#334155">• Doğru diksiyon ve vurgu</text>\n  <text x="575" y="132" text-anchor="middle" font-size="10" fill="#334155">• Dengeli ses tonu</text>\n  <text x="575" y="150" text-anchor="middle" font-size="10" fill="#334155">• Cemaatle göz teması</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
